// n8n stopped while this execution ran (crash or restart). Not parked: the
// item carries no Wazuh alert id, and the alert queue (N8N-1.4) already
// requeues the alert's row at start-up (recv-n8n-start), where the repair
// path completes it. One record here instead of one park per crashed
// sub-execution. With N8N_EVENTBUS_RECOVERY_MODE=simple (compose.yml) n8n
// doesn't call error workflows for crashes at all; this is the fallback.
const j = $input.first().json;
return [{ json: { status: `crash recorded, not parked: ${j.workflow?.name} execution ${j.execution?.id} (${j.execution?.error?.message})`,
  workflow: j.workflow?.name ?? null, execution_id: j.execution?.id ?? null } }];
